/* =====================================================================
   📈 PRODUCTION PLAN · ข้อมูลตั้งต้น PRESS 1 จาก Excel "12. PRESS 1 DECEMBER 26.xlsx"
   ---------------------------------------------------------------------
   1) STORE-SUB: เพิ่ม PART B (B-xxx) ที่ยังไม่มีในระบบ (มีอยู่แล้ว = ไม่แก้) · ชื่อจาก Excel · ลูกค้าตาม PART A
   2) เครื่องจักร 17 เครื่อง + ค่า STD (Q'ty Line · Target Eff · STD Man/Line)
   3) ตาราง Product ของแต่ละเครื่อง (PART A = STORE-PC · PART B = STORE-SUB · Process Code · Total Process · Pcs./Stroke · MC CT · STD MAN)
   - ไม่นำเข้า Actual / PCS (PCS ดึงจาก Forecast / Order ของระบบตามเดือน)
   - รันซ้ำได้: ข้ามเมื่อมีเครื่องของ PRESS1 แล้ว · ใช้กับฐาน CHR-Nexus เท่านั้น (รัน 33_Production_Plan.sql ก่อน)
   ===================================================================== */
SET NOCOUNT ON;
SET XACT_ABORT ON;
IF DB_NAME() <> N'CHR-Nexus' THROW 50000, N'รันสคริปต์นี้กับฐาน CHR-Nexus เท่านั้น', 1;
IF OBJECT_ID('ProductionPlan.Machines', 'U') IS NULL THROW 50000, N'รัน 33_Production_Plan.sql ก่อน', 1;
-- เครื่อง Transfer: Excel ใช้ Stroke = PCS (ไม่คูณ Total Process) · ตั้งให้เฉพาะเครื่องที่ยังเป็นค่าตั้งต้นของระบบ
IF COL_LENGTH('ProductionPlan.Machines', 'StrokeByPcs') IS NOT NULL
    EXEC (N'UPDATE ProductionPlan.Machines SET StrokeByPcs = 1 WHERE Dept = N''PRESS1'' AND StrokeByPcs = 0 AND UpdatedBy = N''SYSTEM''
           AND MachineCode IN (N''TRBS 250-03'', N''TRBS 250-02'', N''NBT Assy'')');
IF EXISTS (SELECT 1 FROM ProductionPlan.Machines WHERE Dept = N'PRESS1') BEGIN PRINT N'มีข้อมูล PRESS1 แล้ว (ข้าม)'; RETURN; END;

DECLARE @sub INT = (SELECT StockID FROM Nexus.Stocks WHERE StockCode = N'STORE-SUB');
DECLARE @pc  INT = (SELECT StockID FROM Nexus.Stocks WHERE StockCode = N'STORE-PC');
IF @sub IS NULL OR @pc IS NULL THROW 50000, N'ไม่พบคลัง STORE-SUB / STORE-PC', 1;

BEGIN TRAN;
DECLARE @r TABLE (No INT, Machine NVARCHAR(50), A NVARCHAR(50), B NVARCHAR(50), Name NVARCHAR(200), ProcCode NVARCHAR(200), TP DECIMAL(9,3), Col DECIMAL(9,3), CT DECIMAL(9,3), Man DECIMAL(9,2));


-- 1) PART B ใหม่ -> STORE-SUB (ชื่อ / ลูกค้า ตามแถวแรกที่พบ)
DECLARE @newB TABLE (B NVARCHAR(50) PRIMARY KEY, Name NVARCHAR(200), Cust NVARCHAR(100));
SELECT x.B, x.Name, x.Cust FROM (
    SELECT r.B, r.Name, pa.Customer AS Cust, ROW_NUMBER() OVER (PARTITION BY r.B ORDER BY r.Machine, r.No) AS rn
    FROM @r r
    OUTER APPLY (SELECT TOP 1 p.Customer FROM Nexus.Parts p JOIN Nexus.PartStocks ps ON ps.PartID = p.PartID AND ps.StockID = @pc WHERE LTRIM(RTRIM(p.PartA)) = r.A) pa
    WHERE r.B LIKE N'B%' ) x
WHERE x.rn = 1
  AND NOT EXISTS (SELECT 1 FROM Nexus.Parts p WHERE LTRIM(RTRIM(p.PartCode)) = x.B OR LTRIM(RTRIM(ISNULL(p.PartB, N''))) = x.B OR LTRIM(RTRIM(ISNULL(p.PartA, N''))) = x.B);

SELECT n.B, ISNULL(n.Name, N''), 0, n.B, 0, 0, N'A', N'N/A', 0, 1, 0, n.Cust, n.B FROM @newB n;
SELECT @sub, p.PartID, 0, 0, 0, 1 FROM Nexus.Parts p JOIN @newB n ON p.PartCode = n.B
WHERE NOT EXISTS (SELECT 1 FROM Nexus.PartStocks s WHERE s.StockID = @sub AND s.PartID = p.PartID);
PRINT N'STORE-SUB: เพิ่ม PART B ' + CAST(@@ROWCOUNT AS NVARCHAR(10)) + N' รายการ';

-- 2) เครื่องจักร + ค่า STD

-- 3) ตาราง Product ของเครื่อง: PART A = STORE-PC (PART A) · PART B = STORE-SUB (B-xxx) / ชิ้นเดียวกับ PART A
SELECT m.MachineID, r.No, a.PartID, COALESCE(b.PartID, ab.PartID), r.ProcCode, r.TP, r.Col, r.CT, r.Man, N'SYSTEM', N'SYSTEM'
FROM @r r
JOIN ProductionPlan.Machines m ON m.Dept = N'PRESS1' AND m.MachineCode = r.Machine
CROSS APPLY (SELECT TOP 1 p.PartID FROM Nexus.Parts p JOIN Nexus.PartStocks ps ON ps.PartID = p.PartID AND ps.StockID = @pc WHERE LTRIM(RTRIM(p.PartA)) = r.A ORDER BY p.PartID) a
OUTER APPLY (SELECT TOP 1 p.PartID FROM Nexus.Parts p JOIN Nexus.PartStocks ps ON ps.PartID = p.PartID AND ps.StockID = @sub WHERE LTRIM(RTRIM(p.PartCode)) = r.B ORDER BY p.PartID) b
OUTER APPLY (SELECT TOP 1 p.PartID FROM Nexus.Parts p JOIN Nexus.PartStocks ps ON ps.PartID = p.PartID AND ps.StockID = @pc WHERE LTRIM(RTRIM(p.PartA)) = r.B ORDER BY p.PartID) ab;
DECLARE @n INT = @@ROWCOUNT, @x INT = (SELECT COUNT(*) FROM @r);
PRINT N'MachineParts: ' + CAST(@n AS NVARCHAR(10)) + N' แถว (Excel ' + CAST(@x AS NVARCHAR(10)) + N')';
IF COL_LENGTH('ProductionPlan.Machines', 'StrokeByPcs') IS NOT NULL
    EXEC (N'UPDATE ProductionPlan.Machines SET StrokeByPcs = 1 WHERE Dept = N''PRESS1'' AND MachineCode IN (N''TRBS 250-03'', N''TRBS 250-02'', N''NBT Assy'')');
-- NBT Assy: Excel ใช้ SPH 100% = 257 (กำหนดเอง)
UPDATE ProductionPlan.Machines SET SphOverride = 257 WHERE Dept = N'PRESS1' AND MachineCode = N'NBT Assy';
COMMIT;
